```sqlite
SELECT A.address_id, A.line_1, A.line_2 FROM Addresses A JOIN Students S ON A.address_id = S.current_address_id GROUP BY A.address_id HAVING COUNT(S.student_id) = (SELECT MAX(student_count) FROM (SELECT COUNT(student_id) AS student_count FROM Students WHERE current_address_id IN (SELECT address_id FROM Addresses) GROUP BY address_id) AS sub);
```

